Задача (исследование в /tmp, НЕ трогай /home/kasiro/Документы/python_projects/SRPC/): проверить готовый обфускатор javascript-obfuscator для будущего проекта. Это шаг 1 из 3 — только исследование.

ЧТО СДЕЛАТЬ (коротко, без лишних экспериментов):
1. cd /tmp && mkdir -p obf_test && cd obf_test && npm init -y && npm i javascript-obfuscator (если уже установлен — пропусти).
2. Создай /tmp/obf_test/test.js:
```js
const MASTER='gU3b08ou68iGQEU9vTcB3Gomv9x617zcgrbZ8dsA00w=';
async function encryptMessage(password, message){
  const enc=new TextEncoder();
  const salt=crypto.getRandomValues(new Uint8Array(16));
  const key=await crypto.subtle.importKey('raw', enc.encode(password), {name:'PBKDF2'}, false, ['deriveBits']);
  const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,salt,iterations:150000,hash:'SHA-256'}, key, 256);
  const aes=await crypto.subtle.importKey('raw', bits, {name:'AES-GCM'}, false, ['encrypt','decrypt']);
  const iv=crypto.getRandomValues(new Uint8Array(12));
  const ct=await crypto.subtle.encrypt({name:'AES-GCM',iv}, aes, enc.encode(message));
  return JSON.stringify({master:MASTER, cipher:Array.from(ct), salt:Array.from(salt), iv:Array.from(iv)});
}
async function decryptMessage(password, payload){
  const p=JSON.parse(payload); const enc=new TextEncoder();
  const key=await crypto.subtle.importKey('raw', enc.encode(password), {name:'PBKDF2'}, false, ['deriveBits']);
  const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new Uint8Array(p.salt),iterations:150000,hash:'SHA-256'}, key, 256);
  const aes=await crypto.subtle.importKey('raw', bits, {name:'AES-GCM'}, false, ['encrypt','decrypt']);
  const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(p.iv)}, aes, new Uint8Array(p.cipher));
  return new TextDecoder().decode(pt);
}
module.exports={encryptMessage,decryptMessage};
```
3. Обфусцируй: node -e "const O=require('javascript-obfuscator');const fs=require('fs');const c=fs.readFileSync('test.js','utf8');const r=O.obfuscate(c,{compact:true,identifierNamesGenerator:'hexadecimal',stringArray:true,stringArrayEncoding:['base64'],controlFlowFlattening:false,deadCodeInjection:false,renameGlobals:true}).getObfuscatedCode();fs.writeFileSync('test.obf.js',r);console.log('OK',c.length,'->',r.length);"
4. Проверь:
   - node --check test.obf.js → синтаксис OK?
   - grep -iE 'master|escrow|key|dek|kek|encrypt|decrypt|password|message|secret|cipher|salt|nonce|iv' test.obf.js | wc -l → сколько вхождений? (важно: 'key' входит в 'monkey'? просто посмотри, что осталось)
   - РАБОТА: node -e "const m=require('./test.obf.js');(async()=>{const p=await m.encryptMessage('пароль','секрет');const t=await m.decryptMessage('пароль',p);console.log('ROUNDTRIP:',t==='секрет'?'OK':'FAIL',t);})().catch(e=>{console.error('ERR',e.message);process.exit(1)})" → ROUNDTRIP: OK?
5. Если stringArrayEncoding:['base64'] ломает (например, ошибка при выполнении) — попробуй без encoding или с ['rc4'].

